    int countResiduePrefixes(string s) {
        int ans = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            set<char> st(s.begin(), s.begin() + i + 1);
            if ((int)st.size() == (i + 1) % 3) ans++;
        }
        return ans;
    }
};

