class Solution {
    public int countResiduePrefixes(String s) {
        int ans = 0;
        for (int i = 0; i < s.length(); i++) {
            Set<Character> st = new HashSet<>();
            for (int j = 0; j <= i; j++) st.add(s.charAt(j));
            if (st.size() == (i + 1) % 3) ans++;
        }
        return ans;
    }
}

